45	  it.todo("counts three Undead Warrior ranks as three types — [sphinx, undead-warrior(1), undead-warrior(2), undead-warrior(3)] is 8");
46	  it.todo("counts repeated Undead Warriors of the same rank once — [sphinx, undead-warrior(2), undead-warrior(2)] is 2");
